require 'utils'
require 'creature'
require 'card'
require 'action'
require 'power'
require 'player'
require 'ironclad'
require 'monster'

PALETTE_MAP = 0x3FF0
HAND_LIMIT = 10

function TIC()
	_G[screen]()
end

-- title
titleSelection = 1
titleOptions = {'New Game','Exit'}

function title()
	if btnp(0) then
		titleSelection = titleSelection - 1
	elseif btnp(1) then
		titleSelection = titleSelection + 1
	end
	titleSelection = limit(titleSelection,1,#titleOptions)

	if btnp(4) then
		if titleSelection == 2 then
			exit()
		elseif titleSelection == 1 then
			screen = 'charselect'
		end
	end

	map(0,0,30,17,0,0)
	local startY = 112
	for i=1,#titleOptions do
		local color = i == titleSelection and 4 or 12
		printShadowed(titleOptions[i],10,startY,color)
		startY = startY + 8
	end
end

-- charselect
charSelection = 1
chars = {'Ironclad','Silent','Defect','Watcher'}

function charselect()
	if btnp(0) then
		charSelection = charSelection - 1
	elseif btnp(1) then
		charSelection = charSelection + 1
	end
	charSelection = limit(charSelection,1,#chars)

	if btnp(4) then
		sync(7,1)
		setupPlayer()
		startCombat()
		screen = 'combat'
	elseif btnp(5) then
		screen = 'title'
	end

	map(0,0,30,17,0,0)
	local startY = 96
	for i=1,#chars do
		local color = i == charSelection and 4 or 12
		printShadowed(chars[i],10,startY,color)
		startY = startY + 8
	end
end

-- combat

player = nil
floor = 1
gold = 0
enemies = {}
deck = {}
drawPile = {}
discardPile = {}
hand = {}
exhaustPile = {}
potions = {'slot','slot','slot'}
energy = 3
maxEnergy = 3
effects = {}
pendingEffects = {}
combatSelection = {type='hand',index=1}
turn = 1
inEnemyTurn = false
function setupPlayer()
	gold = 99
	player = Ironclad:new()
	deck = player:getStartDeck()
end

function startCombat()
	setupEnemies()
	drawPile = {}
	discardPile = {}
	exhaustPile = {}
	hand = {}
	actions = {}
	turn = 0
	inEnemyTurn = false
	runningAction = nil
	for _,card in ipairs(deck) do
		table.insert(drawPile,card:copy())
	end
	shuffle(drawPile)
	player:onCombatStart()
	for _, enemy in ipairs(enemies) do
		enemy:onCombatStart()
	end
	addAction(NewTurnAction:new())
end

function setupEnemies()
	enemies = {}
	local enemy = Cultist:new({ hp=51,maxHp=51,x=110,y=48,width=4,height=4 })
	table.insert(enemies,enemy)
	enemy = Cultist:new({ hp=51,maxHp=51,x=150,y=48,width=4,height=4 })
	table.insert(enemies,enemy)
	enemy = Cultist:new({ hp=51,maxHp=51,x=190,y=48,width=4,height=4 })
	table.insert(enemies,enemy)
end

function combat()
	map(30,0,30,17,0,0)
	player:tick()
	for i=1,#enemies do
		enemies[i]:tick()
	end
	tickEffects()
	tickActions()
	combatControls()
	drawOverlay()
	drawTopBar()
end

function drawTopBar()
	map(0,0,30,1,0,0)
	printShadowed(player.hp .. '/' .. player.maxHp,17,1,3)
	printShadowed(tostring(gold),73,1,4)
	printShadowed(tostring(floor),153,1,12)
	printShadowed(#deck,225,1,12)
	for i = 1,#potions do
		if potions[i] == 'slot' then
			spr(41,96+i*8,0,0)
		end
	end
end

function tickEffects()
	for i=#effects,1,-1 do
		effects[i]:tick()
		if effects[i].isDone then
			table.remove(effects,i)
		end
	end
	for i=#pendingEffects,1,-1 do
		table.insert(effects,pendingEffects[i])
		table.remove(pendingEffects,i)
	end
end

function drawOverlay()
	map(0,2,3,3,4,96,8)
	local energyText = energy .. '/' .. maxEnergy
	local width = strWidth(energyText)
	printShadowed(energyText,16-width/2,105,12)
	spr(38,0,128,0)
	printShadowed(tostring(#drawPile),8,129,12)
	spr(39,232,128,0)
	width = strWidth(tostring(#discardPile))
	printShadowed(tostring(#discardPile),232-width,129,12)
	if #exhaustPile > 0 then
		spr(40,232,120,0)
		width = strWidth(tostring(#exhaustPile))
		printShadowed(tostring(#exhaustPile),232-width,121,12)
	end
	drawHand()
end

function drawHand()
	local handWidth
	local handDistance
	local handStart
	if #hand < 7 then
		handWidth = #hand * 24 + 8
		handDistance = 24
		handStart = 120 - handWidth / 2 + 16 - handDistance
	else
		handWidth = 180
		handDistance = (handWidth - 32) / (#hand - 1)
		handStart = 30
	end
	for i = 1,#hand do
		if not hand[i].isNotInHand then
			hand[i].tx = handStart + i * handDistance
			hand[i].ty = 136
		end
		hand[i].large = false
		if combatSelection.type == 'usecard' and combatSelection.handIndex == i then
			hand[i].ty = 128
		end
		if combatSelection.type ~= 'hand' or combatSelection.index ~= i then
			hand[i]:tick()
		end
	end
	if combatSelection.type == 'hand' and combatSelection.index <= #hand and combatSelection.index >= 1 then
		local index = combatSelection.index
		hand[index].ty = 108
		hand[index].large = true
		hand[index]:tick()
	end
	if combatSelection.type == 'usecard' then
		local cardItem = hand[combatSelection.handIndex]
		local card = cardItem.card
		if card.playerTarget then
			drawSelectionBox(player.x,player.y,8*player.width,8*player.height)
		end
		if card.enemyTarget then
			if card.toAllEnemy then
				for i = 1,#enemies do
					local enemy = enemies[i]
					drawSelectionBox(enemy.x,enemy.y,8*enemy.width,8*enemy.height)
				end
			else
				local enemy = enemies[combatSelection.index]
				drawSelectionBox(enemy.x,enemy.y,8*enemy.width,8*enemy.height)
				drawBezier(20,cardItem.x,cardItem.y-10,math.min(cardItem.x-5,enemy.x-20),enemy.y+enemy.height*4-5,enemy.x+enemy.width*4-4,enemy.y+enemy.height*4)
				spr(74,enemy.x+enemy.width*4-8,enemy.y+enemy.height*4-4,0)
			end
		end
	end
end

function combatControls()
	function cardIsInHand(i) return not hand[i].isNotInHand end
	function enemyIsAlive(i) return enemies[i].alive end
	if combatSelection.type == 'hand' then
		if combatSelection.index == 0 and #hand > 0 and not inEnemyTurn then
			combatSelection.index = nextOrOtherIndexInTableIf(hand,combatSelection.index,cardIsInHand)
		end
		if btnp(2) then
			combatSelection.index = previousOrOtherIndexInTableIf(hand,combatSelection.index,cardIsInHand)
		elseif btnp(3) then
			combatSelection.index = nextOrOtherIndexInTableIf(hand,combatSelection.index,cardIsInHand)
		elseif btnp(4) and combatSelection.index >= 1 and combatSelection.index <= #hand and hand[combatSelection.index].card:canUse() then
			combatSelection.handIndex = combatSelection.index
			combatSelection.index = nextOrOtherIndexInTableIf(enemies,0,enemyIsAlive)
			local card = hand[combatSelection.handIndex].card
			combatSelection.singleEnemy = card.enemyTarget and not card.toAllEnemy
			if combatSelection.index == 0 and combatSelection.singleEnemy then
				combatSelection.index = combatSelection.handIndex
				combatSelection.handIndex = nil
			else
				combatSelection.type = 'usecard'
				if combatSelection.singleEnemy then
					hand[combatSelection.handIndex].card:applyPowers(enemies[combatSelection.index])
				end
			end
		elseif btnp(7) then
			combatSelection.index = 0
		end
	elseif combatSelection.type == 'usecard' then
		if combatSelection.index == 0 or not enemyIsAlive(combatSelection.index) then
			combatSelection.index = nextOrOtherIndexInTableIf(enemies,combatSelection.index,enemyIsAlive)
			if combatSelection.index == 0 and combatSelection.singleEnemy then
				combatSelection.type = 'hand'
				combatSelection.index = combatSelection.handIndex
				hand[combatSelection.handIndex].card:applyPowers()
				combatSelection.handIndex = nil
			end
		end
		if btnp(2) then
			combatSelection.index = previousOrOtherIndexInTableIf(enemies,combatSelection.index,enemyIsAlive)
			local card = hand[combatSelection.handIndex].card
			if card.enemyTarget and not card.toAllEnemy then
				hand[combatSelection.handIndex].card:applyPowers(enemies[combatSelection.index])
			end
		elseif btnp(3) then
			combatSelection.index = nextOrOtherIndexInTableIf(enemies,combatSelection.index,enemyIsAlive)
			local card = hand[combatSelection.handIndex].card
			if card.enemyTarget and not card.toAllEnemy then
				hand[combatSelection.handIndex].card:applyPowers(enemies[combatSelection.index])
			end
		elseif btnp(4) then
			addAction(UseCardAction:new(combatSelection.handIndex,enemies[combatSelection.index]))
			combatSelection.type = 'hand'
			combatSelection.index = previousOrOtherIndexInTableIf(hand,combatSelection.handIndex,cardIsInHand)
			combatSelection.handIndex = nil
		elseif btnp(5) or btnp(7) then
			combatSelection.type = 'hand'
			combatSelection.index = combatSelection.handIndex
			hand[combatSelection.handIndex].card:applyPowers()
			combatSelection.handIndex = nil
			if btnp(7) then
				combatSelection.index = 0
			end
		end
	end
	if btnp(7) and not inEnemyTurn then
		inEnemyTurn = true
		addAction(EndTurnAction:new())
	end
end

function removeHand(index)
	hand[index].card:resetPower()
	table.remove(hand,index)
	if combatSelection.type == 'hand' and combatSelection.index > index then
		combatSelection.index = combatSelection.index - 1
	elseif combatSelection.type == 'usecard' and combatSelection.handIndex > index then
		combatSelection.handIndex = combatSelection.handIndex - 1
	end
end

function previousOrOtherIndexInTableIf(table,currentIndex,condition)
	local previous = previousIndexInTableIf(table,currentIndex,condition)
	if previous == 0 then
		return nextIndexInTableIf(table,currentIndex,condition)
	end
	return previous
end

function nextOrOtherIndexInTableIf(table,currentIndex,condition)
	local next = nextIndexInTableIf(table,currentIndex,condition)
	if next == 0 then
		return nextIndexInTableIf(table,currentIndex,condition)
	end
	return next
end

function previousIndexInTableIf(table,currentIndex,condition)
	currentIndex = limit(currentIndex,1,#table)
	if currentIndex == nil then
		return 0
	end
	local condition = condition or function () return true end
	local previousIndex = currentIndex
	repeat
		previousIndex = previousIndex - 1
	until previousIndex < 1 or condition(previousIndex)
	if previousIndex < 1 then
		if not condition(currentIndex) then
			return 0
		end
		return currentIndex
	end
	return previousIndex
end

function nextIndexInTableIf(table,currentIndex,condition)
	if currentIndex == 0 and #table > 0 and condition(1) then
		return 1
	end
	currentIndex = limit(currentIndex,1,#table)
	if currentIndex == nil then
		return 0
	end
	local condition = condition or function () return true end
	local nextIndex = currentIndex
	repeat
		nextIndex = nextIndex + 1
	until nextIndex > #table or condition(nextIndex)
	if nextIndex > #table then
		if not condition(currentIndex) then
			return 0
		end
		return currentIndex
	end
	return nextIndex
end

-- lose
function lose()
	cls(0)
	player:tick()
	for i=1,#enemies do
		enemies[i]:tick()
	end
	tickEffects()
	drawTopBar()
	local str = 'You Lose!'
	local strWidth = strWidth(str,false,false,3)
	printShadowed('You Lose!',120-strWidth/2,30,3,1,3)
	if btnp(4) or btnp(5) then
		screen = 'title'
		sync(1|4,0)
	end
end

-- main

screen = 'combat'
--sync(32,1)
sync(32|7,1)
setupPlayer()
startCombat()

